use lattice_system_harness::{ScenarioWorld, FakeLlmServer, SseScript, ProviderFixture, FAKE_API_KEY};
use std::{fs, time::{Duration, Instant}, thread};
fn main() -> Result<(), Box<dyn std::error::Error>> {
    let out = std::path::Path::new("/tmp/lattice-377-tmux");
    let world = ScenarioWorld::new("issue377-tmux")?;
    world.set_env("TERM", "tmux-256color");
    world.set_env("LANG", "C.UTF-8");
    world.init_git_project()?;
    let server = FakeLlmServer::start(SseScript::plain("TMUX377 response completed"))?;
    world.wire_provider(ProviderFixture::chat_completions("a"), &server, FAKE_API_KEY)?;
    let provider = world.home().join(".lattice/providers.toml");
    let source = fs::read_to_string(&provider)?;
    fs::write(&provider, format!("{source}\n[providers.local.models.a]\neffort=['low','high']\n[providers.local.models.both]\neffort=['low','high']\n"))?;
    for (name, model, effort) in [("fresh", "both", "high"), ("old", "a", "low"), ("reviewer", "both", "high")] {
        world.write_project_file(&format!(".lattice/agents/{name}/agent.toml"), &format!("schema_version=1\n[agent]\nname='{name}'\nmodel='local/{model}'\neffort='{effort}'\n[prompt]\nsystem='tmux acceptance fixture'\n"))?;
    }
    world.write_project_file(".lattice/agents/broken/agent.toml", "schema_version=1\n[agent]\nname='broken'\nmodel='missing-provider-prefix'\n[prompt]\nsystem='invalid fixture'\n")?;
    fs::write(out.join("fixture-paths.txt"), format!("project={}\nhome={}\n", world.project_dir().display(), world.home().display()))?;
    fs::write(out.join("requests.json"), "[]")?;
    let mut child = world.command("python3").arg(out.join("drive_tmux.py")).arg(std::env::var("LATTICE_BIN")?).spawn()?;
    let deadline = Instant::now() + Duration::from_secs(240);
    let status = loop {
        let requests = server.captured_requests();
        let summaries: Vec<String> = requests.iter().map(|r| format!("{{\"model\":{},\"effort\":{}}}", r.raw["model"], r.raw["reasoning_effort"])).collect();
        fs::write(out.join("requests.tmp"), format!("[{}]", summaries.join(",")))?;
        fs::rename(out.join("requests.tmp"), out.join("requests.json"))?;
        if let Some(status) = child.try_wait()? { break status; }
        if Instant::now() > deadline { child.kill()?; return Err("tmux 实测超过240秒".into()); }
        thread::sleep(Duration::from_millis(50));
    };
    world.stop_daemon().map_err(|e| format!("后台清理失败: {e:?}"))?;
    fs::write(out.join("cleanup.txt"), "ScenarioWorld::stop_daemon 成功；自有后台已清理。\n")?;
    if !status.success() { return Err(format!("tmux 驱动失败: {status}").into()); }
    Ok(())
}
